css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * .08); height: calc(var(--loader-size) * .08); margin: calc(var(--loader-size) * -.04) 0 0 calc(var(--loader-size) * -.04); border-radius: 50%; background: var(--accent); animation: burst calc(var(--loader-speed) * 1.6) ease-out infinite; }
.loader span:nth-child(even) { background: var(--accent-2); }
.loader span:nth-child(1) { --a: 0deg; }
.loader span:nth-child(2) { --a: 36deg; }
.loader span:nth-child(3) { --a: 72deg; }
.loader span:nth-child(4) { --a: 108deg; }
.loader span:nth-child(5) { --a: 144deg; }
.loader span:nth-child(6) { --a: 180deg; }
.loader span:nth-child(7) { --a: 216deg; }
.loader span:nth-child(8) { --a: 252deg; }
.loader span:nth-child(9) { --a: 288deg; }
.loader span:nth-child(10) { --a: 324deg; }
@keyframes burst { 0% { transform: rotate(var(--a)) translateX(0) scale(1); opacity: 1; } 70% { opacity: 1; } 100% { transform: rotate(var(--a)) translateX(calc(var(--loader-size) * .42)) scale(.2); opacity: 0; } }
